    {
      "source": "farmington/statement_of_basis.pdf",
      "locator": "Page 11, Section: fact_sheet",
      "exact_span": "To convert 4Q3 expressed in cfs to 4Q3 expressed as MGD, the constant 1.548 cfs/MGD is used. The 4Q3 is 278.6 MGD and the harmonic mean low flow is 715.8 MGD.",
